def bowl_gradient(v):
    return [4 * v[0] + 2 * v[1] - 6, 2 * v[0] + 4 * v[1] - 6]


def stretched(kappa):
    return (lambda v: 0.5 * (v[0] ** 2 + kappa * v[1] ** 2),
            lambda v: [v[0], kappa * v[1]])


